---@class PVPArenaHomeEntryNode
---@field Text                          	TMPro.TextMeshProUGUI
---@field TimeBg                        	UnityEngine.RectTransform
---@field CommonTimeNode                	UnityEngine.RectTransform
---@field TxtTimeNumber                 	TMPro.TextMeshProUGUI
---@field TxtTimeTitle                  	UnityEngine.UI.Text
---@field ButtonEnter                   	UnityEngine.RectTransform
local PVPArenaHomeEntryNode = Class('PVPArenaHomeEntryNode')

------------ import ------------
local KTool          = CS.Engine.Lib.KTool
local UIEventProxy   = CS.Engine.UI.UIEventProxy
---@type PVPArenaComponent
local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
------------ import ------------

------------ define ------------
local GetTimeHMS2        = CfUtils.GetTimeHMS2
------------ define ------------

function PVPArenaHomeEntryNode:__init()
end

function PVPArenaHomeEntryNode:__delete()
    self.timeNodeEnv = nil
    self.pvpArenaEntryDojo = nil
end

function PVPArenaHomeEntryNode:Awake()
    UIEventProxy.Create(self.ButtonEnter.gameObject).onPointerClick = Bind(self, self.OnClickButtonEnterAction)

    ---@type PVPArenaEntryDojo
    self.pvpArenaEntryDojo = pvpArenaComponent:GetPVPArenaEntryDojo()
    --- 是否是观众
    self.isAudience        = checkNumber(self.pvpArenaEntryDojo.identity) == Constants.PVPArenaIdentity.Audience

    self.__EventRequestEntrySuccess = Events.AddListener(Constants.EventNames.PVPArenaRequestEntrySuccess, Bind(self, self.EventRequestEntrySuccess))
    self.__EventCountDownUpdate = Events.AddListener(Constants.EventNames.PVPArenaCountDownUpdate, Bind(self, self.EventCountDownUpdate))

end

function PVPArenaHomeEntryNode:RemoveEventListener()
    if self.__EventRequestEntrySuccess then
        Events.RemoveListener(Constants.EventNames.PVPArenaRequestEntrySuccess, self.__EventRequestEntrySuccess)
        self.__EventRequestEntrySuccess = nil
    end
    if self.__EventCountDownUpdate then
        Events.RemoveListener(Constants.EventNames.PVPArenaCountDownUpdate, self.__EventCountDownUpdate)
        self.__EventCountDownUpdate = nil
    end
end

function PVPArenaHomeEntryNode:OnDestroy()
    pvpArenaComponent:RemoveCountdown()
    self:RemoveEventListener()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


---------------------------------------------------
--- ui logic begin --
---------------------------------------------------

function PVPArenaHomeEntryNode:RefreshUI(response)
    if response then
        --- 初始化一次入口数据
        pvpArenaComponent:InitEntry(response.data)
    end

    local isShowBattleCountdown = self:GetIsShowBattleCountdown()
    self:RefreshTimeBgShowState(isShowBattleCountdown)
    self.isShowBattleCountdown = isShowBattleCountdown

end

function PVPArenaHomeEntryNode:RefreshTimeBgShowState(isShow)
    KTool.SetActive(self.TimeBg.gameObject, isShow)
end

---EventRequestEntrySuccess
---事件 - 请求入口成功
function PVPArenaHomeEntryNode:EventRequestEntrySuccess()
    local seasonStatus = self.pvpArenaEntryDojo.seasonStatus
    if seasonStatus ~= Constants.PVPArenaSeasonStatus.Battle then
        pvpArenaComponent:RemoveCountdown()
        self:RemoveEventListener()
        KTool.SetActive(self.controller.gameObject, false)
    else
        self:RefreshUI()
    end
end

---EventCountDownUpdate
---事件 - 更新倒计时
function PVPArenaHomeEntryNode:EventCountDownUpdate()
    local pvpArenaEntryDojo = self.pvpArenaEntryDojo
    local nextStageLeftSeconds = pvpArenaEntryDojo.nextStageLeftSeconds
    self.TxtTimeNumber.text = GetTimeHMS2(nextStageLeftSeconds)
    if self.isShowBattleCountdown then
        self.Text.text = pvpArenaEntryDojo.battleNextStageLeftSeconds
    end
end

---------------------------------------------------
--- ui logic end --
---------------------------------------------------

---------------------------------------------------
--- get/set begin --
---------------------------------------------------

function PVPArenaHomeEntryNode:GetIsShowBattleCountdown()
    local pvpArenaEntryDojo = self.pvpArenaEntryDojo
    local battleStatus      = checkNumber(pvpArenaEntryDojo.battleStatus)
    local isBattleReady     = battleStatus == Constants.PVPArenaBattleStatus.Prepare
    --- 是否战斗失败
    local isEnd             = checkNumber(pvpArenaEntryDojo.isEnd) == 1
    local isShowBattleCountdown = not self.isAudience and isBattleReady and not isEnd
    return isShowBattleCountdown
end

---------------------------------------------------
--- get/set end --
---------------------------------------------------


---------------------------------------------------
--- click handler begin --
---------------------------------------------------

function PVPArenaHomeEntryNode:OnClickButtonEnterAction()
    pvpArenaComponent:SetIsEntryPVP(true)
    ---@type PVPArenaUtils
    local PVPArenaUtils = import('Game.Utils.PVPArenaUtils')
    local excludeDialogs = {
        { id = Constants.UITypeIds.UIHomeView },
    }
    PVPArenaUtils.ShowMainDialog(excludeDialogs, true)
end

---------------------------------------------------
--- click handler end --
---------------------------------------------------

return PVPArenaHomeEntryNode